import random, string, typing
from pandas.io.sql import to_sql, read_sql

schars = """!"#$%&\'()*+,-./:;<=>?@[\\]^`{|}~ éèùà$£µç"""

def sql(
    self, sql: str, con: "Engine" = None, dispose: bool = False,
    schema: typing.Any = None, **kwargs: typing.Any
):
    from sqlalchemy import create_engine, inspect

    if con is None:
        con, dispose = create_engine('sqlite:///:memory:'), True
    elif isinstance(con, str):
        con, dispose = create_engine(con), True
    elif isinstance(con, dict):
        con, dispose = create_engine(**con), True

    # tmp name
