        new = self.copy()
        new.columns = [" ".join(col).strip() for col in new.columns.values]
        to_sql(
            new, name=name, con=con, schema=schema, if_exists='replace', method='multi'
        )
    else:
        to_sql(self, name=name, con=con, if_exists='replace', schema=schema, method='multi')
    parse_dates = [c for c in self.columns.values if self[c].dtype.kind == 'M']

    try:
        return read_sql(
            sql, con=con, parse_dates=parse_dates, **kwargs
        )
